contracts/AdvancedERC20.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";

/**
 * @title AdvancedERC20
 * @dev Advanced ERC20 token with comprehensive security features based on paid plans:
 * - Basic Plan: Standard ERC20 with mint authority removal
 * - Professional Plan: + Freezing authority, blacklist, transaction limits, anti-bot, cooldown
 * - Enterprise Plan: + All features + anti-whale, pause, timelock, max wallet
 * 
 * Includes network-aware service fee mechanism for deployment
 */
contract AdvancedERC20 is ERC20, Ownable, Pausable {
    uint8 private _decimals;
    string private _logo;
    string private _website;
    string private _description;
    string private _twitter;
    string private _telegram;
    string private _discord;
    string private _github;
    string private _medium;
    string private _reddit;
    uint256 private _maxTxAmount;
    uint256 private _maxWalletAmount;
    uint256 private _cooldownPeriod;
    uint256 private _timelockDelay;
    
    // Plan-based feature flags
    bool public isProfessionalPlan;
    bool public isEnterprisePlan;
    
    address public freezingAuthority;
    address public blacklistAuthority;
    
    bool public mintAuthorityRemoved;
    bool public antiBotEnabled;
    bool public antiWhaleEnabled;
    bool public timelockEnabled;
    bool public maxWalletEnabled;
    
    // Service fee configuration
    address public immutable platformWallet;
    uint256 public immutable serviceFee;
    uint256 public immutable chainId;
    
    // Network-specific service fee mapping
    mapping(uint256 => uint256) private _networkServiceFees;
    
    // Security mappings
    mapping(address => bool) private _frozen;
    mapping(address => bool) private _blacklisted;
    mapping(address => uint256) private _lastTransactionTime;
    mapping(address => bool) private _isExcludedFromLimits;
    
    // Timelock for administrative functions
    mapping(bytes32 => uint256) private _pendingActions;
    
    event Freeze(address indexed account, bool frozen);
    event Blacklist(address indexed account, bool blacklisted);
    event PlanUpgraded(string plan);
    event ServiceFeePaid(address indexed payer, uint256 amount, uint256 chainId);
    event CooldownUpdated(uint256 newCooldown);
    event MaxWalletUpdated(uint256 newMaxWallet);
    event TimelockActionScheduled(bytes32 indexed actionId, uint256 executeTime);
    event TimelockActionExecuted(bytes32 indexed actionId);
    
    // Network service fee configuration
    // These are the expected service fees for each network (in wei)
    // Updated to be competitive with market rates while maintaining profitability
    uint256 private constant ETHEREUM_BASIC_FEE = 0.05 ether; // ~$100-150
    uint256 private constant ETHEREUM_PROFESSIONAL_FEE = 0.15 ether; // ~$300-450
    uint256 private constant ETHEREUM_ENTERPRISE_FEE = 0.3 ether; // ~$600-900
    
    uint256 private constant POLYGON_BASIC_FEE = 25 * 10**18; // 25 MATIC (~$20-30)
    uint256 private constant POLYGON_PROFESSIONAL_FEE = 75 * 10**18; // 75 MATIC (~$60-90)
    uint256 private constant POLYGON_ENTERPRISE_FEE = 150 * 10**18; // 150 MATIC (~$120-180)
    
    uint256 private constant BSC_BASIC_FEE = 0.05 * 10**18; // 0.05 BNB (~$15-25)
    uint256 private constant BSC_PROFESSIONAL_FEE = 0.15 * 10**18; // 0.15 BNB (~$45-75)
    uint256 private constant BSC_ENTERPRISE_FEE = 0.3 * 10**18; // 0.3 BNB (~$90-150)
    
    uint256 private constant ARBITRUM_BASIC_FEE = 0.01 ether; // ~$20-30
    uint256 private constant ARBITRUM_PROFESSIONAL_FEE = 0.03 ether; // ~$60-90
    uint256 private constant ARBITRUM_ENTERPRISE_FEE = 0.06 ether; // ~$120-180
    
    uint256 private constant OPTIMISM_BASIC_FEE = 0.015 ether; // ~$30-45
    uint256 private constant OPTIMISM_PROFESSIONAL_FEE = 0.045 ether; // ~$90-135
    uint256 private constant OPTIMISM_ENTERPRISE_FEE = 0.09 ether; // ~$180-270
    
    uint256 private constant BASE_BASIC_FEE = 0.01 ether; // ~$20-30
    uint256 private constant BASE_PROFESSIONAL_FEE = 0.03 ether; // ~$60-90
    uint256 private constant BASE_ENTERPRISE_FEE = 0.06 ether; // ~$120-180
    
    // Testnet fees (reduced for testing)
    uint256 private constant SEPOLIA_BASIC_FEE = 0.001 ether; // ~$2-3
    uint256 private constant SEPOLIA_PROFESSIONAL_FEE = 0.003 ether; // ~$6-9
    uint256 private constant SEPOLIA_ENTERPRISE_FEE = 0.006 ether; // ~$12-18
    
    uint256 private constant MUMBAI_BASIC_FEE = 2 * 10**18; // 2 MATIC (~$1.60-2.40)
    uint256 private constant MUMBAI_PROFESSIONAL_FEE = 6 * 10**18; // 6 MATIC (~$4.80-7.20)
    uint256 private constant MUMBAI_ENTERPRISE_FEE = 12 * 10**18; // 12 MATIC (~$9.60-14.40)
    
    uint256 private constant BSC_TESTNET_BASIC_FEE = 0.005 * 10**18; // 0.005 tBNB (~$1.50-2.50)
    uint256 private constant BSC_TESTNET_PROFESSIONAL_FEE = 0.015 * 10**18; // 0.015 tBNB (~$4.50-7.50)
    uint256 private constant BSC_TESTNET_ENTERPRISE_FEE = 0.03 * 10**18; // 0.03 tBNB (~$9-15)
    
    /**
     * @dev Get the expected service fee for a given network and plan
     * @param networkChainId The chain ID of the network
     * @param isProfessional Whether this is a professional plan
     * @param isEnterprise Whether this is an enterprise plan
     * @return The expected service fee in wei
     */
    function getExpectedServiceFee(uint256 networkChainId, bool isProfessional, bool isEnterprise) public pure returns (uint256) {
        if (isEnterprise) {
            if (networkChainId == 1) return ETHEREUM_ENTERPRISE_FEE;
            if (networkChainId == 137) return POLYGON_ENTERPRISE_FEE;
            if (networkChainId == 56) return BSC_ENTERPRISE_FEE;
            if (networkChainId == 42161) return ARBITRUM_ENTERPRISE_FEE;
            if (networkChainId == 10) return OPTIMISM_ENTERPRISE_FEE;
            if (networkChainId == 8453) return BASE_ENTERPRISE_FEE;
            if (networkChainId == 11155111) return SEPOLIA_ENTERPRISE_FEE;
            if (networkChainId == 80001) return MUMBAI_ENTERPRISE_FEE;
            if (networkChainId == 97) return BSC_TESTNET_ENTERPRISE_FEE;
        } else if (isProfessional) {
            if (networkChainId == 1) return ETHEREUM_PROFESSIONAL_FEE;
            if (networkChainId == 137) return POLYGON_PROFESSIONAL_FEE;
            if (networkChainId == 56) return BSC_PROFESSIONAL_FEE;
            if (networkChainId == 42161) return ARBITRUM_PROFESSIONAL_FEE;
            if (networkChainId == 10) return OPTIMISM_PROFESSIONAL_FEE;
            if (networkChainId == 8453) return BASE_PROFESSIONAL_FEE;
            if (networkChainId == 11155111) return SEPOLIA_PROFESSIONAL_FEE;
            if (networkChainId == 80001) return MUMBAI_PROFESSIONAL_FEE;
            if (networkChainId == 97) return BSC_TESTNET_PROFESSIONAL_FEE;
        } else {
            if (networkChainId == 1) return ETHEREUM_BASIC_FEE;
            if (networkChainId == 137) return POLYGON_BASIC_FEE;
            if (networkChainId == 56) return BSC_BASIC_FEE;
            if (networkChainId == 42161) return ARBITRUM_BASIC_FEE;
            if (networkChainId == 10) return OPTIMISM_BASIC_FEE;
            if (networkChainId == 8453) return BASE_BASIC_FEE;
            if (networkChainId == 11155111) return SEPOLIA_BASIC_FEE;
            if (networkChainId == 80001) return MUMBAI_BASIC_FEE;
            if (networkChainId == 97) return BSC_TESTNET_BASIC_FEE;
        }
        
        // Fallback to Ethereum basic fee for unsupported networks
        return ETHEREUM_BASIC_FEE;
    }
    
    modifier onlyFreezingAuthority() {
        require(isProfessionalPlan || isEnterprisePlan, "Freezing not available in basic plan");
        require(msg.sender == freezingAuthority, "Not freezing authority");
        _;
    }
    
    modifier onlyBlacklistAuthority() {
        require(isProfessionalPlan || isEnterprisePlan, "Blacklist not available in basic plan");
        require(msg.sender == blacklistAuthority, "Not blacklist authority");
        _;
    }
    
    modifier notFrozen(address account) {
        if (isProfessionalPlan || isEnterprisePlan) {
            require(!_frozen[account], "Account is frozen");
        }
        _;
    }
    
    modifier notBlacklisted(address account) {
        if (isProfessionalPlan || isEnterprisePlan) {
            require(!_blacklisted[account], "Account is blacklisted");
        }
        _;
    }
    
    modifier onlyEnterprisePlan() {
        require(isEnterprisePlan, "Enterprise plan required");
        _;
    }
    
    modifier checkCooldown() {
        if (antiBotEnabled && (isProfessionalPlan || isEnterprisePlan)) {
            require(
                block.timestamp >= _lastTransactionTime[msg.sender] + _cooldownPeriod,
                "Cooldown period not elapsed"
            );
            _lastTransactionTime[msg.sender] = block.timestamp;
        }
        _;
    }
    
    modifier onlyTimelock() {
        if (timelockEnabled && isEnterprisePlan) {
            require(msg.sender == address(this), "Only timelock can execute");
        }
        _;
    }
    
    constructor(
        string memory name,
        string memory symbol,
        uint8 decimals_,
        uint256 initialSupply,
        address freezingAuthority_,
        string memory logo_,
        string memory website_,
        string memory description_,
        string memory twitter_,
        string memory telegram_,
        string memory discord_,
        string memory github_,
        string memory medium_,
        string memory reddit_,
        bool renounceMint,
        bool enableBlacklist,
        uint256 maxTxAmount_,
        address platformWallet_,
        uint256 serviceFee_,
        bool enableAntiBot,
        uint256 cooldownPeriod_,
        bool enableAntiWhale,
        uint256 maxWalletAmount_,
        bool enablePause,
        bool enableTimelock,
        uint256 timelockDelay_,
        uint256 chainId_
    ) ERC20(name, symbol) Ownable(msg.sender) payable {
        _decimals = decimals_;
        _logo = logo_;
        _website = website_;
        _description = description_;
        _twitter = twitter_;
        _telegram = telegram_;
        _discord = discord_;
        _github = github_;
        _medium = medium_;
        _reddit = reddit_;
        _maxTxAmount = maxTxAmount_;
        _maxWalletAmount = maxWalletAmount_;
        _cooldownPeriod = cooldownPeriod_;
        _timelockDelay = timelockDelay_;
        
        // Set service fee configuration
        platformWallet = platformWallet_;
        serviceFee = serviceFee_;
        chainId = chainId_;
        
        // Determine plan based on features enabled (before fee validation)
        if (enableBlacklist || maxTxAmount_ > 0 || enableAntiBot || cooldownPeriod_ > 0) {
            isProfessionalPlan = true;
        }
        
        // Enterprise plan if advanced features are enabled
        if (enableAntiWhale || enablePause || enableTimelock || maxWalletAmount_ > 0) {
            isEnterprisePlan = true;
            isProfessionalPlan = true;
        }
        
        // Get expected service fee for this network and plan
        uint256 expectedFee = getExpectedServiceFee(chainId_, isProfessionalPlan, isEnterprisePlan);
        
        // Verify service fee payment
        require(msg.value >= expectedFee, "Insufficient service fee for this network and plan");
        
        // Forward service fee to platform wallet
        if (msg.value > 0) {
            (bool success, ) = platformWallet.call{value: msg.value}("");
            require(success, "Failed to forward service fee");
            emit ServiceFeePaid(msg.sender, msg.value, chainId_);
        }
        
        // Set authorities only if plan supports it
        if (isProfessionalPlan || isEnterprisePlan) {
            freezingAuthority = freezingAuthority_;
            blacklistAuthority = enableBlacklist ? msg.sender : address(0);
        }
        
        // Set security features
        antiBotEnabled = enableAntiBot;
        antiWhaleEnabled = enableAntiWhale;
        maxWalletEnabled = maxWalletAmount_ > 0;
        timelockEnabled = enableTimelock;
        
        // Exclude owner from limits initially
        _isExcludedFromLimits[msg.sender] = true;
        
        if (initialSupply > 0) {
            _mint(msg.sender, initialSupply);
        }
        
        if (renounceMint) {
            mintAuthorityRemoved = true;
        }
    }
    
    function decimals() public view virtual override returns (uint8) {
        return _decimals;
    }
    
    function logo() public view returns (string memory) {
        return _logo;
    }
    
    function website() public view returns (string memory) {
        return _website;
    }
    
    function description() public view returns (string memory) {
        return _description;
    }
    
    function twitter() public view returns (string memory) {
        return _twitter;
    }
    
    function telegram() public view returns (string memory) {
        return _telegram;
    }
    
    function discord() public view returns (string memory) {
        return _discord;
    }
    
    function github() public view returns (string memory) {
        return _github;
    }
    
    function medium() public view returns (string memory) {
        return _medium;
    }
    
    function reddit() public view returns (string memory) {
        return _reddit;
    }
    
    function maxTxAmount() public view returns (uint256) {
        return _maxTxAmount;
    }
    
    function maxWalletAmount() public view returns (uint256) {
        return _maxWalletAmount;
    }
    
    function cooldownPeriod() public view returns (uint256) {
        return _cooldownPeriod;
    }
    
    function timelockDelay() public view returns (uint256) {
        return _timelockDelay;
    }
    
    function mint(address to, uint256 amount) public onlyOwner {
        require(!mintAuthorityRemoved, "Mint authority removed");
        _mint(to, amount);
    }
    
    function removeMintAuthority() public onlyOwner {
        require(!mintAuthorityRemoved, "Mint authority already removed");
        mintAuthorityRemoved = true;
    }
    
    function freeze(address account, bool freezeAccount) public onlyFreezingAuthority returns (bool) {
        require(account != address(0), "Cannot freeze zero address");
        _frozen[account] = freezeAccount;
        emit Freeze(account, freezeAccount);
        return true;
    }
    
    function isFrozen(address account) public view returns (bool) {
        return _frozen[account];
    }
    
    function setFreezingAuthority(address newAuthority) public onlyOwner {
        require(isProfessionalPlan || isEnterprisePlan, "Plan upgrade required");
        freezingAuthority = newAuthority;
    }
    
    function blacklist(address account, bool blacklistAccount) public onlyBlacklistAuthority returns (bool) {
        require(account != address(0), "Cannot blacklist zero address");
        _blacklisted[account] = blacklistAccount;
        emit Blacklist(account, blacklistAccount);
        return true;
    }
    
    function isBlacklisted(address account) public view returns (bool) {
        return _blacklisted[account];
    }
    
    function setBlacklistAuthority(address newAuthority) public onlyOwner {
        require(isProfessionalPlan || isEnterprisePlan, "Plan upgrade required");
        blacklistAuthority = newAuthority;
    }
    
    function upgradeToProfessional() public onlyOwner {
        require(!isProfessionalPlan, "Already professional plan");
        isProfessionalPlan = true;
        emit PlanUpgraded("Professional");
    }
    
    function upgradeToEnterprise() public onlyOwner {
        require(!isEnterprisePlan, "Already enterprise plan");
        require(isProfessionalPlan, "Must upgrade to professional first");
        isEnterprisePlan = true;
        emit PlanUpgraded("Enterprise");
    }
    
    function setCooldownPeriod(uint256 newCooldown) public onlyOwner {
        require(isProfessionalPlan || isEnterprisePlan, "Plan upgrade required");
        _cooldownPeriod = newCooldown;
        emit CooldownUpdated(newCooldown);
    }
    
    function setMaxWalletAmount(uint256 newMaxWallet) public onlyOwner {
        require(isEnterprisePlan, "Enterprise plan required");
        _maxWalletAmount = newMaxWallet;
        emit MaxWalletUpdated(newMaxWallet);
    }
    
    function excludeFromLimits(address account, bool excluded) public onlyOwner {
        _isExcludedFromLimits[account] = excluded;
    }
    
    function isExcludedFromLimits(address account) public view returns (bool) {
        return _isExcludedFromLimits[account];
    }
    
    function scheduleAction(bytes32 actionId) public onlyOwner {
        require(timelockEnabled && isEnterprisePlan, "Timelock not enabled");
        require(_pendingActions[actionId] == 0, "Action already scheduled");
        _pendingActions[actionId] = block.timestamp + _timelockDelay;
        emit TimelockActionScheduled(actionId, block.timestamp + _timelockDelay);
    }
    
    function executeAction(bytes32 actionId) public onlyOwner {
        require(timelockEnabled && isEnterprisePlan, "Timelock not enabled");
        require(_pendingActions[actionId] > 0, "Action not scheduled");
        require(block.timestamp >= _pendingActions[actionId], "Timelock not elapsed");
        delete _pendingActions[actionId];
        emit TimelockActionExecuted(actionId);
    }
    
    function transfer(address to, uint256 amount) 
        public 
        virtual 
        override 
        whenNotPaused
        notFrozen(msg.sender) 
        notBlacklisted(msg.sender) 
        notFrozen(to) 
        notBlacklisted(to)
        checkCooldown
        returns (bool) 
    {
        if (_maxTxAmount > 0 && (isProfessionalPlan || isEnterprisePlan)) {
            require(amount <= _maxTxAmount, "Amount exceeds max transaction limit");
        }
        
        // Check max wallet limit for Enterprise plan
        if (maxWalletEnabled && isEnterprisePlan && !_isExcludedFromLimits[to]) {
            require(
                balanceOf(to) + amount <= _maxWalletAmount,
                "Max wallet limit exceeded"
            );
        }
        
        return super.transfer(to, amount);
    }
    
    function transferFrom(address from, address to, uint256 amount) 
        public 
        virtual 
        override 
        whenNotPaused
        notFrozen(from) 
        notBlacklisted(from) 
        notFrozen(to) 
        notBlacklisted(to)
        checkCooldown
        returns (bool) 
    {
        if (_maxTxAmount > 0 && (isProfessionalPlan || isEnterprisePlan)) {
            require(amount <= _maxTxAmount, "Amount exceeds max transaction limit");
        }
        
        // Check max wallet limit for Enterprise plan
        if (maxWalletEnabled && isEnterprisePlan && !_isExcludedFromLimits[to]) {
            require(
                balanceOf(to) + amount <= _maxWalletAmount,
                "Max wallet limit exceeded"
            );
        }
        
        return super.transferFrom(from, to, amount);
    }
    
    function approve(address spender, uint256 amount) 
        public 
        virtual 
        override 
        whenNotPaused
        notFrozen(msg.sender) 
        notBlacklisted(msg.sender) 
        notFrozen(spender) 
        notBlacklisted(spender)
        returns (bool) 
    {
        return super.approve(spender, amount);
    }
    
    function renounceOwnership() public virtual override onlyEnterprisePlan {
        super.renounceOwnership();
    }
    
    function pause() public onlyOwner {
        require(isEnterprisePlan, "Enterprise plan required");
        _pause();
    }
    
    function unpause() public onlyOwner {
        require(isEnterprisePlan, "Enterprise plan required");
        _unpause();
    }
    
    // Emergency function to recover any ETH sent to contract (except service fees)
    function emergencyWithdraw() public onlyOwner {
        uint256 balance = address(this).balance;
        require(balance > 0, "No ETH to withdraw");
        
        (bool success, ) = owner().call{value: balance}("");
        require(success, "Failed to withdraw ETH");
    }
}

contracts/CrossChainBridge.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import "@openzeppelin/contracts/utils/cryptography/EIP712.sol";

/**
 * @title Enhanced CrossChainBridge
 * @dev Advanced cross-chain bridge for supporting smaller/newer blockchain networks
 * Features: Multi-signature validation, gas optimization, network-specific configurations
 */
contract CrossChainBridge is ReentrancyGuard, Pausable, Ownable, EIP712 {
    using SafeERC20 for IERC20;
    using ECDSA for bytes32;

    // Bridge events
    event TokenLocked(
        address indexed token,
        address indexed sender,
        uint256 amount,
        uint256 targetChainId,
        address targetRecipient,
        bytes32 indexed transferId,
        uint256 timestamp
    );
    
    event TokenUnlocked(
        address indexed token,
        address indexed recipient,
        uint256 amount,
        uint256 sourceChainId,
        bytes32 indexed transferId,
        uint256 timestamp
    );

    event ValidatorAdded(address indexed validator);
    event ValidatorRemoved(address indexed validator);
    event ChainSupported(uint256 indexed chainId, bool supported);
    event TokenSupported(address indexed token, bool supported);
    event FeeUpdated(uint256 indexed chainId, uint256 fee);
    event MinAmountUpdated(uint256 indexed chainId, uint256 minAmount);
    event MaxAmountUpdated(uint256 indexed chainId, uint256 maxAmount);

    // Bridge state
    mapping(bytes32 => bool) public processedTransfers;
    mapping(uint256 => ChainConfig) public chainConfigs;
    mapping(address => TokenConfig) public tokenConfigs;
    mapping(address => bool) public validators;
    mapping(address => uint256) public validatorNonces;
    
    // Multi-signature configuration
    uint256 public requiredSignatures;
    uint256 public validatorCount;
    
    // Gas optimization for smaller networks
    uint256 public constant GAS_LIMIT_BUFFER = 50000;
    uint256 public constant MAX_BATCH_SIZE = 10;
    
    // Structs for better organization
    struct ChainConfig {
        bool supported;
        uint256 fee; // Fee in basis points (1 = 0.01%)
        uint256 minAmount;
        uint256 maxAmount;
        uint256 gasLimit;
        uint256 blockTime;
        bool requiresMultipleSignatures;
        uint256 maxDailyVolume;
        uint256 dailyVolume;
        uint256 lastVolumeReset;
    }
    
    struct TokenConfig {
        bool supported;
        uint256 decimals;
        bool isNative;
        uint256 maxDailyVolume;
        uint256 dailyVolume;
        uint256 lastVolumeReset;
    }
    
    struct TransferRequest {
        address token;
        address sender;
        uint256 amount;
        uint256 targetChainId;
        address targetRecipient;
        uint256 timestamp;
        uint256 nonce;
    }

    // EIP-712 domain separator
    bytes32 public constant TRANSFER_TYPEHASH = keccak256(
        "TransferRequest(address token,address sender,uint256 amount,uint256 targetChainId,address targetRecipient,uint256 timestamp,uint256 nonce)"
    );

    /**
     * @dev Configure chain settings (internal)
     */
    function _configureChain(
        uint256 chainId,
        bool supported,
        uint256 fee,
        uint256 minAmount,
        uint256 maxAmount,
        uint256 gasLimit,
        uint256 blockTime,
        bool requiresMultipleSignatures,
        uint256 maxDailyVolume
    ) internal {
        chainConfigs[chainId] = ChainConfig({
            supported: supported,
            fee: fee,
            minAmount: minAmount,
            maxAmount: maxAmount,
            gasLimit: gasLimit,
            blockTime: blockTime,
            requiresMultipleSignatures: requiresMultipleSignatures,
            maxDailyVolume: maxDailyVolume,
            dailyVolume: 0,
            lastVolumeReset: block.timestamp
        });
        
        emit ChainSupported(chainId, supported);
    }

    /**
     * @dev Configure chain settings (external admin function)
     */
    function configureChain(
        uint256 chainId,
        bool supported,
        uint256 fee,
        uint256 minAmount,
        uint256 maxAmount,
        uint256 gasLimit,
        uint256 blockTime,
        bool requiresMultipleSignatures,
        uint256 maxDailyVolume
    ) external onlyOwner {
        _configureChain(chainId, supported, fee, minAmount, maxAmount, gasLimit, blockTime, requiresMultipleSignatures, maxDailyVolume);
    }

    /**
     * @dev Initialize default chain configurations
     */
    function _initializeDefaultChains() internal {
        // Configure popular networks with reasonable defaults
        _configureChain(1, true, 10, 1e16, 1000e18, 300000, 12, false, 1000000e18); // Ethereum
        _configureChain(137, true, 5, 1e16, 1000000e18, 300000, 2, false, 5000000e18); // Polygon
        _configureChain(56, true, 5, 1e16, 1000000e18, 300000, 3, false, 5000000e18); // BSC
        _configureChain(250, true, 3, 1e16, 1000000e18, 250000, 1, false, 3000000e18); // Fantom
        _configureChain(43114, true, 5, 1e16, 1000000e18, 800000, 2, false, 3000000e18); // Avalanche
        _configureChain(42161, true, 3, 1e16, 1000000e18, 1000000, 1, false, 5000000e18); // Arbitrum
        _configureChain(10, true, 3, 1e16, 1000000e18, 300000, 2, false, 5000000e18); // Optimism
        _configureChain(804, true, 3, 1e16, 1000000e18, 300000, 3, false, 5000000e18); // PulseChain
        _configureChain(100, true, 5, 1e16, 1000000e18, 300000, 5, false, 2000000e18); // Gnosis Chain
        _configureChain(8453, true, 5, 1e16, 1000000e18, 300000, 2, false, 2000000e18); // Base
        _configureChain(59144, true, 5, 1e16, 1000000e18, 300000, 12, false, 2000000e18); // Linea
        _configureChain(1101, true, 3, 1e16, 1000000e18, 300000, 1, false, 3000000e18); // Polygon zkEVM
        _configureChain(324, true, 3, 1e16, 1000000e18, 300000, 1, false, 3000000e18); // zkSync Era
        _configureChain(534352, true, 3, 1e16, 1000000e18, 300000, 2, false, 3000000e18); // Scroll
        _configureChain(1284, true, 5, 1e16, 1000000e18, 150000, 12, false, 1000000e18); // Moonbeam
        _configureChain(1285, true, 5, 1e16, 1000000e18, 150000, 12, false, 1000000e18); // Moonriver
    }

    constructor() EIP712("CrossChainBridge", "1.0") Ownable(msg.sender) {
        validators[msg.sender] = true;
        validatorCount = 1;
        requiredSignatures = 1;
        
        // Initialize default chain configurations
        _initializeDefaultChains();
    }

    /**
     * @dev Lock tokens for cross-chain transfer
     */
    function lockTokens(
        address token,
        uint256 amount,
        uint256 targetChainId,
        address targetRecipient
    ) external nonReentrant whenNotPaused {
        require(tokenConfigs[token].supported, "Bridge: Token not supported");
        require(chainConfigs[targetChainId].supported, "Bridge: Chain not supported");
        require(amount > 0, "Bridge: Amount must be greater than 0");
        require(targetRecipient != address(0), "Bridge: Invalid recipient");
        
        ChainConfig storage chainConfig = chainConfigs[targetChainId];
        TokenConfig storage tokenConfig = tokenConfigs[token];
        
        // Check amount limits
        require(amount >= chainConfig.minAmount, "Bridge: Amount below minimum");
        require(amount <= chainConfig.maxAmount, "Bridge: Amount above maximum");
        
        // Check daily volume limits
        _checkDailyVolumeLimits(chainConfig, tokenConfig, amount);
        
        // Calculate and collect fee
        uint256 fee = (amount * chainConfig.fee) / 10000;
        uint256 transferAmount = amount - fee;
        
        // Transfer tokens from user to bridge
        IERC20(token).safeTransferFrom(msg.sender, address(this), amount);
        
        // Transfer fee to owner (or fee collector)
        if (fee > 0) {
            IERC20(token).safeTransfer(owner(), fee);
        }

        // Generate transfer ID
        bytes32 transferId = _generateTransferId(
            token,
            msg.sender,
            transferAmount,
            targetChainId,
            targetRecipient
        );

        // Update daily volumes
        _updateDailyVolumes(chainConfig, tokenConfig, transferAmount);

        emit TokenLocked(
            token,
            msg.sender,
            transferAmount,
            targetChainId,
            targetRecipient,
            transferId,
            block.timestamp
        );
    }

    /**
     * @dev Unlock tokens from cross-chain transfer (validator only)
     */
    function unlockTokens(
        address token,
        address recipient,
        uint256 amount,
        uint256 sourceChainId,
        bytes32 transferId,
        bytes calldata signatures
    ) external nonReentrant whenNotPaused {
        require(validators[msg.sender], "Bridge: Only validators can unlock");
        require(!processedTransfers[transferId], "Bridge: Transfer already processed");
        require(tokenConfigs[token].supported, "Bridge: Token not supported");
        require(amount > 0, "Bridge: Amount must be greater than 0");
        require(recipient != address(0), "Bridge: Invalid recipient");

        // Verify signatures
        require(_verifySignatures(transferId, signatures), "Bridge: Invalid signatures");

        processedTransfers[transferId] = true;

        // Transfer tokens to recipient
        IERC20(token).safeTransfer(recipient, amount);

        emit TokenUnlocked(
            token,
            recipient,
            amount,
            sourceChainId,
            transferId,
            block.timestamp
        );
    }

    /**
     * @dev Batch unlock tokens for gas optimization on smaller networks
     */
    function batchUnlockTokens(
        address[] calldata tokens,
        address[] calldata recipients,
        uint256[] calldata amounts,
        uint256[] calldata sourceChainIds,
        bytes32[] calldata transferIds,
        bytes[] calldata signatures
    ) external nonReentrant whenNotPaused {
        require(validators[msg.sender], "Bridge: Only validators can unlock");
        require(tokens.length <= MAX_BATCH_SIZE, "Bridge: Batch too large");
        require(
            tokens.length == recipients.length &&
            tokens.length == amounts.length &&
            tokens.length == sourceChainIds.length &&
            tokens.length == transferIds.length &&
            tokens.length == signatures.length,
            "Bridge: Array length mismatch"
        );

        for (uint256 i = 0; i < tokens.length; i++) {
            require(!processedTransfers[transferIds[i]], "Bridge: Transfer already processed");
            require(tokenConfigs[tokens[i]].supported, "Bridge: Token not supported");
            require(amounts[i] > 0, "Bridge: Amount must be greater than 0");
            require(recipients[i] != address(0), "Bridge: Invalid recipient");

            // Verify signature
            require(_verifySignature(transferIds[i], signatures[i]), "Bridge: Invalid signature");

            processedTransfers[transferIds[i]] = true;
            IERC20(tokens[i]).safeTransfer(recipients[i], amounts[i]);

            emit TokenUnlocked(
                tokens[i],
                recipients[i],
                amounts[i],
                sourceChainIds[i],
                transferIds[i],
                block.timestamp
            );
        }
    }

    // Admin functions
    function addValidator(address validator) external onlyOwner {
        require(validator != address(0), "Bridge: Invalid validator address");
        require(!validators[validator], "Bridge: Validator already exists");
        
        validators[validator] = true;
        validatorCount++;
        
        emit ValidatorAdded(validator);
    }

    function removeValidator(address validator) external onlyOwner {
        require(validators[validator], "Bridge: Validator does not exist");
        require(validatorCount > requiredSignatures, "Bridge: Too few validators");
        
        validators[validator] = false;
        validatorCount--;
        
        emit ValidatorRemoved(validator);
    }

    function setRequiredSignatures(uint256 _requiredSignatures) external onlyOwner {
        require(_requiredSignatures <= validatorCount, "Bridge: Too many required signatures");
        require(_requiredSignatures > 0, "Bridge: At least one signature required");
        
        requiredSignatures = _requiredSignatures;
    }

    function configureToken(
        address token,
        bool supported,
        uint256 decimals,
        bool isNative,
        uint256 maxDailyVolume
    ) external onlyOwner {
        tokenConfigs[token] = TokenConfig({
            supported: supported,
            decimals: decimals,
            isNative: isNative,
            maxDailyVolume: maxDailyVolume,
            dailyVolume: 0,
            lastVolumeReset: block.timestamp
        });
        
        emit TokenSupported(token, supported);
    }

    // View functions
    function getChainConfig(uint256 chainId) external view returns (ChainConfig memory) {
        return chainConfigs[chainId];
    }

    function getTokenConfig(address token) external view returns (TokenConfig memory) {
        return tokenConfigs[token];
    }

    function isTransferProcessed(bytes32 transferId) external view returns (bool) {
        return processedTransfers[transferId];
    }

    function getBridgeBalance(address token) external view returns (uint256) {
        return IERC20(token).balanceOf(address(this));
    }

    function estimateGasForUnlock(uint256 chainId) external view returns (uint256) {
        ChainConfig storage config = chainConfigs[chainId];
        return config.gasLimit + GAS_LIMIT_BUFFER;
    }

    // Internal functions
    function _generateTransferId(
        address token,
        address sender,
        uint256 amount,
        uint256 targetChainId,
        address targetRecipient
    ) internal returns (bytes32) {
        return keccak256(
            abi.encodePacked(
                token,
                sender,
                amount,
                targetChainId,
                targetRecipient,
                block.chainid,
                block.timestamp,
                validatorNonces[sender]++
            )
        );
    }

    function _verifySignatures(bytes32 transferId, bytes calldata signatures) internal view returns (bool) {
        require(signatures.length >= requiredSignatures * 65, "Bridge: Insufficient signatures");
        
        bytes32 hash = _hashTypedDataV4(transferId);
        address[] memory signers = new address[](requiredSignatures);
        
        for (uint256 i = 0; i < requiredSignatures; i++) {
            bytes memory signature = signatures[i * 65:(i + 1) * 65];
            address signer = hash.recover(signature);
            
            if (!validators[signer]) {
                return false;
            }
            
            // Check for duplicate signatures
            for (uint256 j = 0; j < i; j++) {
                if (signers[j] == signer) {
                    return false;
                }
            }
            
            signers[i] = signer;
        }
        
        return true;
    }

    function _verifySignature(bytes32 transferId, bytes calldata signature) internal view returns (bool) {
        bytes32 hash = _hashTypedDataV4(transferId);
        address signer = hash.recover(signature);
        return validators[signer];
    }

    function _checkDailyVolumeLimits(
        ChainConfig storage chainConfig,
        TokenConfig storage tokenConfig,
        uint256 amount
    ) internal view {
        // Reset daily volumes if 24 hours have passed
        if (block.timestamp - chainConfig.lastVolumeReset >= 1 days) {
            // Volume will be reset in _updateDailyVolumes
        } else {
            require(
                chainConfig.dailyVolume + amount <= chainConfig.maxDailyVolume,
                "Bridge: Chain daily volume limit exceeded"
            );
            require(
                tokenConfig.dailyVolume + amount <= tokenConfig.maxDailyVolume,
                "Bridge: Token daily volume limit exceeded"
            );
        }
    }

    function _updateDailyVolumes(
        ChainConfig storage chainConfig,
        TokenConfig storage tokenConfig,
        uint256 amount
    ) internal {
        // Reset daily volumes if 24 hours have passed
        if (block.timestamp - chainConfig.lastVolumeReset >= 1 days) {
            chainConfig.dailyVolume = 0;
            chainConfig.lastVolumeReset = block.timestamp;
        }
        
        if (block.timestamp - tokenConfig.lastVolumeReset >= 1 days) {
            tokenConfig.dailyVolume = 0;
            tokenConfig.lastVolumeReset = block.timestamp;
        }
        
        chainConfig.dailyVolume += amount;
        tokenConfig.dailyVolume += amount;
    }

    // Emergency functions
    function emergencyWithdraw(address token, address to, uint256 amount) external onlyOwner {
        IERC20(token).safeTransfer(to, amount);
    }

    function pause() external onlyOwner {
        _pause();
    }

    function unpause() external onlyOwner {
        _unpause();
    }
}

